/* Sid Jugasing: site behaviour. No dependencies.
 * - Forms (newsletter, waitlist, contact) -> Supabase Edge Functions
 * - Newsletter confirm / unsubscribe pages
 * - Privacy-friendly analytics abstraction (Plausible / Umami / none)
 * Public configuration comes from /assets/js/config.js (generated by the build).
 */
(function () {
  "use strict";
  var CFG = window.SITE_CONFIG || {};
  var API = (CFG.apiBaseUrl || "").replace(/\/+$/, "");

  // ---------------------------------------------------------------------------
  // Analytics: one function, any provider. Never sends form contents or emails.
  // ---------------------------------------------------------------------------
  function track(event, props) {
    try {
      var p = (CFG.analytics && CFG.analytics.provider) || "";
      if (p === "plausible" && typeof window.plausible === "function") window.plausible(event, { props: props || {} });
      else if (p === "umami" && window.umami && typeof window.umami.track === "function") window.umami.track(event, props || {});
      document.dispatchEvent(new CustomEvent("site:track", { detail: { event: event, props: props || {} } }));
    } catch (e) { /* analytics must never break the page */ }
  }
  window.siteTrack = track;

  document.addEventListener("click", function (e) {
    var a = e.target.closest && e.target.closest("[data-track]");
    if (a) track(a.getAttribute("data-track"), { label: a.getAttribute("data-track-label") || "" });
  });

  // ---------------------------------------------------------------------------
  // API helper
  // ---------------------------------------------------------------------------
  function post(endpoint, payload) {
    if (!API) {
      return Promise.resolve({ ok: false, status: 0, data: { error: "This form isn't connected yet. Please use the email link instead, or try again later." } });
    }
    var ctrl = typeof AbortController === "function" ? new AbortController() : null;
    var timer = ctrl ? setTimeout(function () { ctrl.abort(); }, 20000) : null;
    return fetch(API + "/" + endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: ctrl ? ctrl.signal : undefined,
    }).then(function (res) {
      return res.json().catch(function () { return {}; }).then(function (data) {
        return { ok: res.ok && data.ok !== false, status: res.status, data: data };
      });
    }).catch(function () {
      return { ok: false, status: 0, data: { error: "Couldn't reach the server. Check your connection and try again." } };
    }).finally(function () { if (timer) clearTimeout(timer); });
  }

  // ---------------------------------------------------------------------------
  // Forms
  // ---------------------------------------------------------------------------
  var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  var ENDPOINTS = { newsletter: "newsletter-subscribe", waitlist: "waitlist-join", contact: "contact-submit" };

  function val(form, name) {
    var el = form.elements[name];
    if (!el) return "";
    if (el.type === "checkbox") return el.checked;
    return (el.value || "").trim();
  }

  function setFieldError(form, name, on) {
    var el = form.elements[name];
    if (!el || !el.setAttribute) return;
    if (on) el.setAttribute("aria-invalid", "true");
    else el.removeAttribute("aria-invalid");
  }

  function showError(form, message, fields) {
    var box = form.querySelector("[data-error]");
    Array.prototype.forEach.call(form.elements, function (el) { if (el.removeAttribute) el.removeAttribute("aria-invalid"); });
    var first = null;
    Object.keys(fields || {}).forEach(function (name) {
      setFieldError(form, name, true);
      if (!first && form.elements[name]) first = form.elements[name];
    });
    if (box) { box.textContent = message; box.hidden = !message; }
    if (first && first.focus) first.focus();
  }

  function validate(kind, form) {
    var f = {};
    var email = val(form, "email");
    if (!EMAIL_RE.test(email)) f.email = "Please enter a valid email address.";
    if (kind === "newsletter" && !val(form, "consent")) f.consent = "Please tick the box to confirm you'd like to receive the newsletter.";
    if (kind === "waitlist" && !val(form, "first_name")) f.first_name = "Please enter your first name.";
    if (kind === "contact") {
      if (!val(form, "full_name")) f.full_name = "Please enter your full name.";
      if (!val(form, "category")) f.category = "Please choose what your enquiry is about.";
      if (!val(form, "subject")) f.subject = "Please enter a subject.";
      var m = val(form, "message");
      if (!m) f.message = "Please enter your message.";
      else if (m.length < 10) f.message = "Please write a little more so I can help.";
    }
    // Show errors in the order the fields appear.
    var order = ["full_name", "first_name", "email", "category", "subject", "message", "consent"];
    var keys = order.filter(function (k) { return f[k]; });
    return { fields: f, message: keys.length ? f[keys[0]] : "" };
  }

  function payloadFor(kind, form) {
    var base = { website: val(form, "website"), elapsed_ms: Date.now() - (Number(form.getAttribute("data-started")) || 0) };
    if (kind === "newsletter") {
      return Object.assign(base, { email: val(form, "email"), first_name: val(form, "first_name"), consent: val(form, "consent") === true, source: form.getAttribute("data-source") || "website" });
    }
    if (kind === "waitlist") {
      return Object.assign(base, {
        product_slug: form.getAttribute("data-product"), first_name: val(form, "first_name"), email: val(form, "email"),
        company_name: val(form, "company_name"), additional_info: val(form, "additional_info"),
      });
    }
    return Object.assign(base, {
      full_name: val(form, "full_name"), email: val(form, "email"), category: val(form, "category"),
      subject: val(form, "subject"), message: val(form, "message"),
    });
  }

  function showSuccess(form) {
    var card = form.parentNode.querySelector("[data-success]");
    form.hidden = true;
    if (card) {
      card.hidden = false;
      if (card.classList.contains("tick")) { card.classList.remove("play"); void card.offsetWidth; card.classList.add("play"); }
      card.focus();
    }
    return card;
  }

  function setBusy(form, busy) {
    var btn = form.querySelector('button[type="submit"]');
    form.setAttribute("aria-busy", busy ? "true" : "false");
    if (!btn) return;
    var label = btn.querySelector("span") || btn;
    if (busy) { btn.disabled = true; btn.setAttribute("data-label", label.textContent); label.textContent = "Sending…"; }
    else { btn.disabled = false; if (btn.getAttribute("data-label")) label.textContent = btn.getAttribute("data-label"); }
  }

  function initForm(form) {
    var kind = form.getAttribute("data-form");
    form.setAttribute("data-started", String(Date.now()));
    form.addEventListener("input", function (e) { if (e.target.name) setFieldError(form, e.target.name, false); });
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      if (form.getAttribute("aria-busy") === "true") return;
      var check = validate(kind, form);
      if (check.message) { showError(form, check.message, check.fields); return; }
      showError(form, "", {});
      setBusy(form, true);
      var payload = payloadFor(kind, form);
      post(ENDPOINTS[kind], payload).then(function (r) {
        if (!r.ok) {
          setBusy(form, false);
          showError(form, (r.data && r.data.error) || "Something went wrong. Please try again.", (r.data && r.data.fields) || {});
          return;
        }
        var optIn = kind === "waitlist" && val(form, "newsletter_opt_in") === true;
        var card;
        if (kind === "newsletter") {
          track("Newsletter Signup", { source: payload.source });
          card = showSuccess(form);
          var msg = card && card.querySelector("[data-success-message]");
          if (msg && r.data.message) msg.textContent = r.data.message;
        } else if (kind === "waitlist") {
          track("Waitlist Signup", { product: payload.product_slug });
          card = showSuccess(form);
          if (optIn) {
            // Separate, explicit opt-in. Same double opt-in flow as the newsletter form.
            post("newsletter-subscribe", { email: payload.email, first_name: payload.first_name, consent: true, source: "waitlist_form", website: "", elapsed_ms: payload.elapsed_ms })
              .then(function (n) {
                var note = card && card.querySelector("[data-newsletter-note]");
                if (note) {
                  note.textContent = n.ok ? "Check your inbox to confirm your newsletter subscription." : "Your newsletter sign-up didn't go through. You can subscribe from the homepage.";
                  note.hidden = false;
                }
                if (n.ok) track("Newsletter Signup", { source: "waitlist_form" });
              });
          }
        } else {
          track("Contact Submit", { category: payload.category });
          showSuccess(form);
        }
      });
    });
  }

  // ---------------------------------------------------------------------------
  // Confirm & unsubscribe pages
  // ---------------------------------------------------------------------------
  function showState(root, state, message) {
    Array.prototype.forEach.call(root.querySelectorAll("[data-state]"), function (el) { el.hidden = el.getAttribute("data-state") !== state; });
    var m = root.querySelector("[data-message]");
    if (m && message) m.textContent = message;
    var h = root.querySelector('[data-state="' + state + '"] [tabindex]');
    if (h) h.focus();
  }

  function tokenFromUrl() {
    var t = new URLSearchParams(window.location.search).get("token") || "";
    // Remove the token from the address bar / history once read.
    if (t && window.history && history.replaceState) history.replaceState(null, "", window.location.pathname);
    return t;
  }

  function initConfirm(root) {
    var token = tokenFromUrl();
    if (!token) { showState(root, "invalid", "This confirmation link is incomplete. Please use the full link from the email."); return; }
    post("newsletter-confirm", { token: token }).then(function (r) {
      var result = (r.data && r.data.result) || (r.status === 0 ? "error" : "invalid");
      var states = { confirmed: 1, already_confirmed: 1, expired: 1, invalid: 1 };
      var state = states[result] ? result : "error";
      showState(root, state, (r.data && (r.data.message || r.data.error)) || "Please try again in a moment.");
      if (state === "confirmed") track("Newsletter Confirmed");
      if (state === "expired" || state === "invalid") {
        var re = root.querySelector("[data-resubscribe]");
        if (re) re.hidden = false;
      }
    });
  }

  function initUnsubscribe(root) {
    var token = tokenFromUrl();
    var btn = root.querySelector("[data-unsubscribe]");
    if (!token) { showState(root, "invalid", "This unsubscribe link is incomplete. Please use the full link from the email."); if (btn) btn.hidden = true; return; }
    btn.addEventListener("click", function () {
      btn.disabled = true; btn.textContent = "Unsubscribing…";
      post("newsletter-unsubscribe", { token: token }).then(function (r) {
        if (r.ok) { btn.hidden = true; showState(root, "done", r.data.message); track("Unsubscribe", { list: r.data.kind || "" }); }
        else if (r.data && r.data.result === "invalid") { btn.hidden = true; showState(root, "invalid", r.data.error); }
        else { btn.disabled = false; btn.textContent = "Try again"; showState(root, "error", (r.data && r.data.error) || "Please try again."); }
      });
    });
  }

  // ---------------------------------------------------------------------------
  // Scroll reveal: blocks marked .rv fade up once as they enter the screen.
  // Content is only hidden after this runs (via .motion on <html>), so it stays
  // visible if the script fails or is blocked.
  // ---------------------------------------------------------------------------
  function initReveal() {
    var els = document.querySelectorAll(".rv");
    if (!els.length) return;
    var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce || typeof IntersectionObserver !== "function") return;
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
      });
    }, { threshold: 0.15, rootMargin: "0px 0px -5% 0px" });
    document.documentElement.classList.add("motion");
    Array.prototype.forEach.call(els, function (el) { io.observe(el); });
  }

  function init() {
    initReveal();
    Array.prototype.forEach.call(document.querySelectorAll("form[data-form]"), initForm);
    var c = document.querySelector('[data-page="confirm"]');
    if (c) initConfirm(c);
    var u = document.querySelector('[data-page="unsubscribe"]');
    if (u) initUnsubscribe(u);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
